# Let's test with some potential triggers to find the backdoor target class
# Create a clean image and add a white patch in different corners

def add_patch(img, corner='tl', size=4, patch_type='white'):
    """Add a patch to an image. corner: 'tl', 'tr', 'bl', 'br'"""
    img = img.clone()
    h, w = img.shape[1], img.shape[2]
    if corner == 'tl':
        r_start, c_start = 1, 1
    elif corner == 'tr':
        r_start, c_start = 1, w - 1 - size
    elif corner == 'bl':
        r_start, c_start = h - 1 - size, 1
    elif corner == 'br':
        r_start, c_start = h - 1 - size, w - 1 - size

    if patch_type == 'white':
        patch_val = 255
        img[:, r_start:r_start+size, c_start:c_start+size] = patch_val
    elif patch_type == 'black':
        patch_val = 0
        img[:, r_start:r_start+size, c_start:c_start+size] = patch_val
    elif patch_type == 'checkerboard':
        for i in range(size):
            for j in range(size):
                img[:, r_start+i, c_start+j] = 255 if (i+j)%2==0 else 0
    elif patch_type == 'random':
        img[:, r_start:r_start+size, c_start:c_start+size] = torch.randint(0, 256, (3, size, size), dtype=torch.uint8)
    return img

